/// The whole schema as a catalog.
pub fn catalog() -> Catalog {
    Catalog::new(TABLES.iter().map(|(name, pkey, columns)| {
        DbTable::new(
            *name,
            [*pkey],
            columns
                .iter()
                .map(|(column, ty)| DbColumn::new(*column, ty.clone()))
                .collect(),
        )
    }))
}

/// The relationship `name` declared on `table`.
///
/// # Panics
///
/// On a name the schema does not declare, which is a typo in a test.
pub fn rel(table: &str, name: &str) -> &'static Rel {
    RELS.iter()
        .find(|rel| rel.table == table && rel.name == name)
        .unwrap_or_else(|| panic!("no relationship `{name}` on `{table}`"))
}

/// The primary-key column of `table`.
///
/// # Panics
///
/// On an unknown table name.
pub fn pkey(table: &str) -> &'static str {
    TABLES
        .iter()
        .find(|(name, _, _)| *name == table)
        .map(|(_, pkey, _)| *pkey)
        .unwrap_or_else(|| panic!("no table `{table}`"))
}

/// The columns of `table` in declaration order.
///
/// # Panics
///
/// On an unknown table name.
pub fn columns(table: &str) -> &'static [(&'static str, ValueType)] {
    TABLES
        .iter()
        .find(|(name, _, _)| *name == table)
        .map(|(_, _, columns)| *columns)
        .unwrap_or_else(|| panic!("no table `{table}`"))
}
